# ============================================================
# NUTRICOACH SUPER PACK
# Additional utilities, analytics, planning, safety helpers,
# export tools, streaks, goals, meal insights, and UI helpers.
# ============================================================

SUPER_VERSION = "10K-style Super Edition"
APP_BUILD = "2026.09"

def safe_float(value, default=0.0):
    try:
        return float(value)
    except (TypeError, ValueError):
        return default

def pct(current, target):
    target = safe_float(target)
    current = safe_float(current)
    if target <= 0:
        return 0.0
    return max(0.0, min(current / target, 1.0))

def clamp(value, low, high):
    return max(low, min(value, high))

def format_kcal(value):
    return f"{safe_float(value):,.0f} kcal"

def format_grams(value):
    return f"{safe_float(value):,.1f} g"

def target_status(current, target):
    current = safe_float(current)
    target = safe_float(target)
    if target <= 0:
        return "No target"
    ratio = current / target
    if ratio < 0.5:
        return "Low"
    if ratio < 0.85:
        return "On the way"
    if ratio <= 1.10:
        return "Near target"
    return "Above target"

def daily_score(t, target):
    components = [
        pct(t["Calories"], target["Calories"]),
        pct(t["Protein"], target["Protein"]),
        pct(t["Fiber"], target["Fiber"]),
    ]
    # A simple descriptive dashboard score, not a medical assessment.
    score = sum(components) / len(components) * 100
    return int(clamp(score, 0, 100))

def food_gap_summary(t, target):
    gaps = {
        "protein": max(target["Protein"] - t["Protein"], 0),
        "fiber": max(target["Fiber"] - t["Fiber"], 0),
        "calories": max(target["Calories"] - t["Calories"], 0),
    }
    largest = max(gaps, key=gaps.get)
    return largest, gaps

def get_historical_daily_totals(days=30):
    con = db()
    rows = con.execute("""
        SELECT day,
               COALESCE(SUM(calories),0),
               COALESCE(SUM(protein),0),
               COALESCE(SUM(carbs),0),
               COALESCE(SUM(fat),0),
               COALESCE(SUM(fiber),0)
        FROM food_log
        GROUP BY day
        ORDER BY day DESC
        LIMIT ?
    """, (days,)).fetchall()
    con.close()
    return rows

def get_workout_days(days=30):
    con = db()
    rows = con.execute("""
        SELECT day,
               COUNT(*),
               COALESCE(SUM(minutes),0),
               COALESCE(SUM(calories),0)
        FROM workouts
        WHERE completed=1
        GROUP BY day
        ORDER BY day DESC
        LIMIT ?
    """, (days,)).fetchall()
    con.close()
    return rows

def get_measurement_history():
    con = db()
    rows = con.execute("""
        SELECT day, weight, waist, chest, arms, legs, shoulders
        FROM measurements
        ORDER BY day ASC, id ASC
    """).fetchall()
    con.close()
    return rows

def current_streak():
    # Counts consecutive days with either logged food or completed workout.
    active = set()
    con = db()
    for row in con.execute("SELECT DISTINCT day FROM food_log").fetchall():
        active.add(row[0])
    for row in con.execute("SELECT DISTINCT day FROM workouts WHERE completed=1").fetchall():
        active.add(row[0])
    con.close()

    streak = 0
    d = date.today()
    while d.isoformat() in active:
        streak += 1
        d -= timedelta(days=1)
    return streak

def meal_completion_count():
    con = db()
    row = con.execute(
        "SELECT COUNT(*) FROM meal_status WHERE day=? AND done=1",
        (TODAY,)
    ).fetchone()
    con.close()
    return int(row[0]) if row else 0

def weekly_food_average():
    rows = get_historical_daily_totals(7)
    if not rows:
        return None
    return {
        "Calories": sum(r[1] for r in rows) / len(rows),
        "Protein": sum(r[2] for r in rows) / len(rows),
        "Carbs": sum(r[3] for r in rows) / len(rows),
        "Fat": sum(r[4] for r in rows) / len(rows),
        "Fiber": sum(r[5] for r in rows) / len(rows),
    }

def weekly_workout_summary():
    rows = get_workout_days(7)
    if not rows:
        return {"days": 0, "minutes": 0, "calories": 0}
    return {
        "days": len(rows),
        "minutes": sum(r[2] for r in rows),
        "calories": sum(r[3] for r in rows),
    }

def save_goal_note(note):
    # Store lightweight notes in the profile JSON so no extra dependency is needed.
    p = load_profile()
    p["goal_note"] = note
    save_profile(p)

def load_goal_note():
    return load_profile().get("goal_note", "")

def meal_swap_options(meal_name, diet):
    common = {
        "Breakfast": [
            "Oats + milk/soy milk + banana",
            "Poha + curd/soy yogurt + fruit",
            "Besan chilla + curd/tofu",
            "Eggs + oats + fruit",
        ],
        "Lunch": [
            "Rice + dal + vegetables",
            "Roti + chana + salad",
            "Rice + rajma + vegetables",
            "Roti + paneer/tofu + vegetables",
        ],
        "Snack": [
            "Roasted chana + fruit",
            "Curd/soy yogurt + banana",
            "Peanuts + seasonal fruit",
            "Sprouts chaat",
        ],
        "Dinner": [
            "Roti + paneer/tofu + vegetables",
            "Rice + dal + salad",
            "Roti + chana + vegetables",
            "Khichdi + curd/soy yogurt",
        ],
    }
    options = common.get(meal_name, [])
    if diet == "Vegan":
        options = [
            x.replace("curd", "soy yogurt")
             .replace("paneer", "tofu")
             .replace("milk", "soy milk")
             .replace("Eggs", "tofu scramble")
             .replace("egg", "tofu")
            for x in options
        ]
    return options

def recommendation_list():
    recs = []
    if remaining["Protein"] >= 35:
        recs.append("Prioritize a protein-rich meal next.")
    if remaining["Fiber"] >= 7:
        recs.append("Add vegetables, dal, beans, sprouts or fruit.")
    if water < targets["Water"] * 0.5:
        recs.append("Drink some water before your next meal.")
    if not today_workout() or not today_workout()[1]:
        recs.append("Complete today's automatic workout when practical.")
    if not recs:
        recs.append("Your dashboard is reasonably balanced; keep your next meal simple.")
    return recs

def generate_grocery_list(plan):
    # Converts the meal plan into a practical shopping checklist.
    text = "\n".join(
        f"{d['Breakfast']}; {d['Lunch']}; {d['Snack']}; {d['Dinner']}"
        for d in plan
    ).lower()

    categories = {
        "Protein foods": ["eggs", "chicken", "fish", "paneer", "tofu", "soy chunks",
                          "dal", "chana", "rajma", "curd", "yogurt"],
        "Carbohydrates": ["rice", "roti", "poha", "oats", "bread", "khichdi"],
        "Fruit": ["banana", "apple", "orange", "fruit", "seasonal"],
        "Vegetables": ["vegetables", "salad", "sprouts"],
        "Fats": ["peanuts", "peanut butter", "seeds"],
    }

    found = {}
    for category, words in categories.items():
        found[category] = sorted({w for w in words if w in text})
    return found

def nutrition_alerts():
    alerts = []
    if totals["Protein"] < targets["Protein"] * 0.5:
        alerts.append("Protein intake is still below half of today's target.")
    if totals["Fiber"] < targets["Fiber"] * 0.5:
        alerts.append("Fiber intake is still below half of today's target.")
    if totals["Calories"] > targets["Calories"] * 1.15:
        alerts.append("Logged calories are above the daily target estimate.")
    if water < targets["Water"] * 0.5:
        alerts.append("Water intake is below half of the estimated daily target.")
    return alerts

# ------------------------------------------------------------
# SUPER DASHBOARD — appears as an expandable intelligence layer
# ------------------------------------------------------------
with st.expander("✨ NutriCoach Intelligence Center", expanded=False):
    s1, s2, s3, s4 = st.columns(4)
    s1.metric("Daily balance", f"{daily_score(totals, targets)} / 100")
    s2.metric("Current streak", f"{current_streak()} days")
    s3.metric("Meals completed", f"{meal_completion_count()} / 4")
    ws = weekly_workout_summary()
    s4.metric("Workouts this week", str(ws["days"]))

    st.markdown("### 🧠 Action queue")
    for item in recommendation_list():
        st.write("• " + item)

    alerts = nutrition_alerts()
    if alerts:
        st.markdown("### ⚠️ Dashboard alerts")
        for item in alerts:
            st.warning(item)
    else:
        st.success("No dashboard alerts based on the information currently logged.")

    avg = weekly_food_average()
    if avg:
        st.markdown("### 📊 Recent food averages")
        a, b, c, d = st.columns(4)
        a.metric("Avg calories", f"{avg['Calories']:.0f}")
        b.metric("Avg protein", f"{avg['Protein']:.0f} g")
        c.metric("Avg carbs", f"{avg['Carbs']:.0f} g")
        d.metric("Avg fiber", f"{avg['Fiber']:.0f} g")

    st.markdown("### 🛒 14-day grocery helper")
    grocery = generate_grocery_list(st.session_state.diet_plan)
    for category, items in grocery.items():
        if items:
            st.write(f"**{category}:** " + ", ".join(items))

# ------------------------------------------------------------
# EXTRA PROGRESS INSIGHTS
# ------------------------------------------------------------
if nav == "📊 Progress":
    with st.expander("📈 Deeper progress insights"):
        history = get_measurement_history()
        if len(history) >= 2:
            first = history[0]
            last = history[-1]
            weight_change = safe_float(last[1]) - safe_float(first[1])
            st.write(
                f"Weight change across recorded measurements: "
                f"**{weight_change:+.1f} kg**."
            )
            if last[2] and first[2]:
                waist_change = safe_float(last[2]) - safe_float(first[2])
                st.write(
                    f"Waist change across recorded measurements: "
                    f"**{waist_change:+.1f} cm**."
                )
        else:
            st.info("Add at least two measurements for trend insights.")

# ------------------------------------------------------------
# EXPORT CENTER
# ------------------------------------------------------------
if nav == "🍽️ Food":
    with st.expander("📦 Export today's nutrition"):
        foods = get_today_food()
        if foods:
            import pandas as pd
            export_df = pd.DataFrame(foods)
            csv_data = export_df.to_csv(index=False).encode("utf-8")
            st.download_button(
                "⬇️ Download today's food CSV",
                data=csv_data,
                file_name=f"nutricoach_food_{TODAY}.csv",
                mime="text/csv"
            )
        else:
            st.info("Log food first, then export it.")

# ------------------------------------------------------------
# SMART GOAL NOTE
# ------------------------------------------------------------
if nav == "👤 Profile":
    with st.expander("📝 Personal goal note"):
        note = st.text_area(
            "What matters most to you right now?",
            value=load_goal_note(),
            placeholder="Example: I want to become consistent with protein and workouts."
        )
        if st.button("Save goal note"):
            save_goal_note(note)
            st.success("Goal note saved.")

# ------------------------------------------------------------
# DATA SAFETY / RESET
# ------------------------------------------------------------
with st.sidebar:
    st.title("NutriCoach")
    st.caption(SUPER_VERSION)
    st.write("Your data is stored locally in `nutricoach.db`.")
    st.divider()
    st.write("### Data tools")
    st.write("Use the normal app controls to add and remove individual food entries.")
    st.caption(
        "Before deleting the database file, make a backup if you want to keep "
        "your history."
    )

